(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[2802],{3383:(n,e,t)=>{(window.__NEXT_P=window.__NEXT_P||[]).push(["/zh-CN/syntax",function(){return t(7271)}])},7271:(n,e,t)=>{"use strict";t.r(e),t.d(e,{default:()=>m});var r=t(7876),o=t(7328),i=t.n(o),a=t(4213),d=t(8419);function m(){return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsxs)(i(),{children:[(0,r.jsx)("title",{children:"语法 - ".concat(a.Ix)}),(0,r.jsx)("meta",{name:"keywords",content:a.hN}),(0,r.jsx)("meta",{name:"description",content:a.f4}),(0,r.jsx)("meta",{name:"viewport",content:"width=device-width, initial-scale=1"})]}),(0,r.jsx)(d.A,{editorId:"md-syntax-zh",value:"!!! tip\n\n在使用行内语法（如加粗、斜体等）时，如果需要加粗的文本中包含特殊字符，并且加粗标识符（如 `**`）前后紧挨着其他字符，请务必在第二个标识符（如 `**`）后添加至少一个空格。否则，Markdown 解析器可能无法正确识别加粗效果。\n\n示例：\n\n错误写法：`AAA**I have a dream.**BBB`\n\n正确写法：`AAA**I have a dream.** BBB`\n\n同样的问题也适用于其它行内语法（如斜体等），请注意在语法标识符后添加空格以确保正确解析。\n\n!!!\n\n## \uD83D\uDC36 标题\n\n```markdown\n## 标题\n```\n\n---\n\n## \uD83D\uDC31 加粗\n\n**I have a dream that one day this nation will rise up.**\n\n```markdown\n**I have a dream that one day this nation will rise up.**\n```\n\n---\n\n## \uD83D\uDC2D 斜体\n\n_It is a dream deeply rooted in the American dream._\n\n```markdown\n_It is a dream deeply rooted in the American dream._\n```\n\n---\n\n## \uD83D\uDC39 删除线\n\n~~It is a dream deeply rooted in the American dream.~~\n\n```markdown\n~~It is a dream deeply rooted in the American dream.~~\n```\n\n---\n\n## \uD83D\uDC3B 超链接\n\n[md-editor-rt](https://imzbf.github.io/md-editor-rt/)\n\n```markdown\n[md-editor-rt](https://imzbf.github.io/md-editor-rt/)\n```\n\n---\n\n## \uD83D\uDC3C 图片\n\n![描述文字](https://imzbf.github.io/md-editor-rt/imgs/mark_emoji.gif 'title')\n\n```markdown\n![描述文字](https://imzbf.github.io/md-editor-rt/imgs/mark_emoji.gif 'title')\n```\n\n---\n\n## \uD83D\uDE49 下划线\n\n下划线使用原生 HTML 标签 `<u>`，工具栏按钮和快捷键都会插入这种写法。由于默认 `html: false`，它会显示为普通文本。需要渲染下划线时，请通过 [markdownItConfig](https://imzbf.github.io/md-editor-rt/zh-CN/api#%F0%9F%8D%A4%20markdownItConfig) 显式开启 `html: true`。\n\n```markdown\n<u>So even though we face the difficulties of today and tomorrow, I still have a dream.</u>\n```\n\n---\n\n## \uD83D\uDE4A 上标\n\nI have a dream that one day this nation will rise up.^[1]^\n\n```markdown\nI have a dream that one day this nation will rise up.^[1]^\n```\n\n---\n\n## \uD83D\uDC12 下标\n\nI have a dream that one day this nation will rise up.~[2]~\n\n```markdown\nI have a dream that one day this nation will rise up.~[2]~\n```\n\n---\n\n## \uD83D\uDC30 行内代码\n\n`md-editor-rt`\n\n```markdown\n`md-editor-rt`\n```\n\n---\n\n## \uD83E\uDD8A 块级代码\n\n````markdown\n```js\nimport { MdEditor } from 'md-editor-rt';\nimport 'md-editor-rt/lib/style.css';\n```\n````\n\n### \uD83D\uDD8D 行高亮\n\n\\>= v7.0.0\n\n在语言标识后添加 `{...}` 可高亮指定代码行。行号从 `1` 开始，多个行号使用逗号分隔，连续区间使用 `起始行-结束行`；支持 `js {2,4-5}` 和 `js{2,4-5}` 两种写法。\n\n```js {2,4-5}\nimport { MdEditor } from 'md-editor-rt';\nimport 'md-editor-rt/lib/style.css';\nconst value = '# Hello';\nconst editor = <MdEditor value={value} />;\nexport default editor;\n```\n\n````markdown\n```js {2,4-5}\nimport { MdEditor } from 'md-editor-rt';\nimport 'md-editor-rt/lib/style.css';\nconst value = '# Hello';\nconst editor = <MdEditor value={value} />;\nexport default editor;\n```\n````\n\n行高亮与 `showCodeRowNumber` 相互独立，隐藏行号后仍会保留高亮效果。\n\n### \uD83D\uDDC4 代码组合\n\n```shell [id:yarn]\nyarn add md-editor-rt\n```\n\n```shell [id:npm]\nnpm install md-editor-rt\n```\n\n```shell [id:pnpm]\npnpm install md-editor-rt\n```\n\n````markdown\n```shell [id:yarn]\nyarn add md-editor-rt\n```\n\n```shell [id:npm]\nnpm install md-editor-rt\n```\n\n```shell [id:pnpm]\npnpm install md-editor-rt\n```\n````\n\n### \uD83E\uDD0C\uD83C\uDFFB 强制折叠\n\n```js ::close\nimport { MdEditor } from 'md-editor-rt';\nimport 'md-editor-rt/lib/style.css';\n```\n\n````markdown\n```js ::close\nimport { MdEditor } from 'md-editor-rt';\nimport 'md-editor-rt/lib/style.css';\n```\n````\n\n### \uD83D\uDC50 强制展开\n\n```js ::open\nimport { MdEditor } from 'md-editor-rt';\nimport 'md-editor-rt/lib/style.css';\n```\n\n````markdown\n```js ::open\nimport { MdEditor } from 'md-editor-rt';\nimport 'md-editor-rt/lib/style.css';\n```\n````\n\n据其他编辑器的了解，目前没有其他编辑器使用类似的语法，如果需要拷贝你的内容到其他编辑器展示时，请谨慎使用该语法。\n\n---\n\n## \uD83D\uDC3B‍❄️ 引用\n\n> 引用：《I Have a Dream》\n\n```markdown\n> 引用：《I Have a Dream》\n```\n\n---\n\n## \uD83D\uDC28 有序列表\n\n1. So even though we face the difficulties of today and tomorrow, I still have a dream.\n2. It is a dream deeply rooted in the American dream.\n3. I have a dream that one day this nation will rise up.\n\n```markdown\n1. So even though we face the difficulties of today and tomorrow, I still have a dream.\n2. It is a dream deeply rooted in the American dream.\n3. I have a dream that one day this nation will rise up.\n```\n\n---\n\n## \uD83D\uDC2F 无序列表\n\n- So even though we face the difficulties of today and tomorrow, I still have a dream.\n- It is a dream deeply rooted in the American dream.\n- I have a dream that one day this nation will rise up.\n\n```markdown\n- So even though we face the difficulties of today and tomorrow, I still have a dream.\n- It is a dream deeply rooted in the American dream.\n- I have a dream that one day this nation will rise up.\n```\n\n---\n\n## \uD83E\uDD81 任务列表\n\n- [ ] 周五\n- [ ] 周六\n- [x] 周天\n\n```markdown\n- [ ] 周五\n- [ ] 周六\n- [x] 周天\n```\n\n支持在预览模块切换任务状态的[示例](https://imzbf.github.io/md-editor-rt/zh-CN/demo#☑%EF%B8%8F%20可切换状态的任务列表)\n\n---\n\n## \uD83D\uDC2E 表格\n\n| 表头 1 |  表头 2  | 表头 3 | 表头 4 |\n| :----- | :------: | -----: | ------ |\n| 左对齐 | 中间对齐 | 右对齐 | 默认   |\n\n```markdown\n| 表头 1 |  表头 2  | 表头 3 | 表头 4 |\n| :----- | :------: | -----: | ------ |\n| 左对齐 | 中间对齐 | 右对齐 | 默认   |\n```\n\n---\n\n## \uD83D\uDC37 数学公式\n\n有两种模式\n\n### \uD83D\uDC3D 行内\n\n$x+y^{2x}$ \\(\\xrightarrow[under]{over}\\)\n\n```markdown\n$x+y^{2x}$\n\n\x3c!-- or --\x3e\n\n\\(\\xrightarrow[under]{over}\\)\n```\n\n---\n\n### \uD83D\uDC38 块级\n\n$$\\sqrt[3]{x}$$\n\n\\[\\xrightarrow[under]{over}\\]\n\n```markdown\n$$\n\\sqrt[3]{x}\n$$\n\n\x3c!-- or --\x3e\n\n\\[\\xrightarrow[under]{over}\\]\n```\n\n更多公式示例参考：[https://katex.org/docs/supported.html](https://katex.org/docs/supported.html)\n\n---\n\n## \uD83D\uDC35 图表\n\n```mermaid\n---\ntitle: Example Git diagram\n---\ngitGraph\n   commit\n   commit\n   branch develop\n   checkout develop\n   commit\n   commit\n   checkout main\n   merge develop\n   commit\n   commit\n```\n\n````markdown\n```mermaid\n---\ntitle: Example Git diagram\n---\ngitGraph\n   commit\n   commit\n   branch develop\n   checkout develop\n   commit\n   commit\n   checkout main\n   merge develop\n   commit\n   commit\n```\n````\n\n更多图形示例参考：[https://mermaid.js.org/syntax/flowchart.html](https://mermaid.js.org/syntax/flowchart.html)\n\n---\n\n## \uD83D\uDE48 提示\n\n!!! note 支持的类型\n\nnote、abstract、info、tip、success、question、warning、failure、danger、bug、example、quote、hint、caution、error、attention\n\n!!!\n\n```markdown\n!!! note 支持的类型\n\nnote、abstract、info、tip、success、question、warning\n\nfailure、danger、bug、example、quote、hint、caution、error、attention\n\n!!!\n```\n\n---\n\n## \uD83D\uDCCA Echarts\n\n\\>= v6.0.0\n\n从 v7.x 开始，默认解析器使用 `JSON5.parse`，且顶层必须是对象。支持未加引号的属性名、单引号字符串、注释和尾随逗号等 JSON5 数据语法。JSON5 只解析数据，因此不支持函数、变量引用、`new` 或调用表达式。\n\n```echarts\n{\n  tooltip: {\n    trigger: 'axis'\n  },\n  xAxis: {\n    type: 'category',\n    data: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']\n  },\n  yAxis: {\n    type: 'value'\n  },\n  series: [\n    {\n      data: [150, 230, 224, 218, 135, 147, 260],\n      type: 'line'\n    }\n  ]\n}\n```\n\n````markdown\n```echarts\n{\n  tooltip: {\n    trigger: 'axis'\n  },\n  xAxis: {\n    type: 'category',\n    data: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']\n  },\n  yAxis: {\n    type: 'value'\n  },\n  series: [\n    {\n      data: [150, 230, 224, 218, 135, 147, 260],\n      type: 'line'\n    }\n  ]\n}\n```\n````\n\n!!! warning\n\n从 v7.x 开始，默认解析不会执行 JavaScript。若需函数回调等仅 JavaScript 支持的配置，可通过 `editorExtensions.echarts.parseOption` 自定义解析器。自定义解析器会接收原始 Markdown 内容，请仅在输入可信或完成严格校验后使用。\n\n!!!\n\n## \uD83E\uDD84 链接引用\n\n[md-editor-rt][1]\n\n[1]: https://imzbf.github.io/md-editor-rt/\n\n```markdown\n[md-editor-rt][1]\n\n[1]: https://imzbf.github.io/md-editor-rt/\n```\n"})]})}},8419:(n,e,t)=>{"use strict";t.d(e,{A:()=>c});var r=t(7876),o=t(8854),i=t(1120),a=t(6510),d=t(9385),m=t(1281),s=t(4232);let l=(n,e)=>{history.replaceState({},"","".concat(location.pathname,"#").concat(e.text))},h=n=>{let e=(0,a.G)(n=>n.setting),t=(0,s.useRef)(null),o=(0,s.useRef)(!0),i=(0,s.useCallback)((n,e)=>{if(!e||!o.current)return;let r=(0,d.Uw)(),i=e.offsetTop-t.current.scrollTop;i>200?r(t.current,e.offsetTop-200):i<100&&r(t.current,e.offsetTop-100)},[]);return(0,r.jsx)("div",{className:"catalog",onMouseEnter:()=>{o.current=!1},onMouseLeave:()=>{o.current=!0},children:(0,r.jsx)("div",{ref:t,className:"affix",children:(0,r.jsx)(m.M,{scrollElementOffsetTop:10,editorId:n.editorId,theme:e.theme,scrollElement:"html",onClick:l,onActive:i})})})},c=n=>{let{showCodeRowNumber:e=!0}=n,t=(0,i.u)(),d=(0,a.G)(n=>n.setting);return(0,r.jsx)("div",{className:"container",children:(0,r.jsxs)("div",{className:"doc",children:[(0,r.jsx)("div",{className:"content",children:(0,r.jsx)(o.A,{id:n.editorId,language:t,theme:d.theme,value:n.value,previewTheme:d.previewTheme,showCodeRowNumber:e,codeTheme:d.codeTheme})}),(0,r.jsx)(h,{editorId:n.editorId})]})})}}},n=>{n.O(0,[6791,636,6593,8792],()=>n(n.s=3383)),_N_E=n.O()}]);